import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem66 preserva operação e exige identidade',()=>{for(const [id,titulo] of [['bufeMWJJrnyiM5TBcKXW','Ventilador de Coluna Ventisol Turbo 6 Pás 30cm Preto 8234'],['c1R3iVzduEndTWAhxXvO','Torneira Elétrica De Parede - Loren Easy Lorenzetti Acabamento Branco Cor Branco 220v 5.5KW']]){let p={id,titulo,preco:'preservado',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/excelente|eficiência|instalação prática/i);}});
